        var custom_args = args.slice(custom_args_idx + 1)
        for arg in custom_args:
            if arg.begins_with("--port="): port = int(arg.split("=")[1])
            elif arg.begins_with("--clients="): client_count = int(arg.split("=")[1])
            elif arg.begins_with("--frames="): frames = int(arg.split("=")[1])
            elif arg.begins_with("--score-deltas="): 
                for s in arg.split("=")[1].split(","): score_deltas.append(int(s))
            elif arg.begins_with("--out="): out_path = arg.split("=")[1]

    # Server setup
    server_peer = ENetMultiplayerPeer.new()
    server_peer.create_server(port, client_count + 1)
    get_tree().set_multiplayer(SceneMultiplayer.new(), NodePath("/root/Main"))
    get_tree().get_multiplayer().multiplayer_peer = server_peer

    # Spawn host player
    spawn_player(1)

    # Clients setup
    for i in range(client_count):
        var c_peer = ENetMultiplayerPeer.new()
        c_peer.create_client("127.0.0.1", port)
        var c_mp = SceneMultiplayer.new()
