        var dummy = Node.new()
        dummy.name = "Client" + str(i)
        get_tree().root.add_child(dummy)
        get_tree().set_multiplayer(c_mp, NodePath(node_path))
        c_mp.multiplayer_peer = c_peer
        client_peers.append(c_mp)

    # Simulation loop
    for f in range(frames):
        await get_tree().process_frame
        # After a few frames, apply scores
        if f == 5:
            for i in range(client_count):
                var client_id = client_peers[i].get_unique_id()
                var p = get_node("/root/Main/Players/" + str(client_id))
                if p:
                    p.update_score.rpc(score_deltas[i])

    write_json()
    get_tree().quit()

func spawn_player(id):
    var p = player_scene.instantiate()
    p.name = str(id)
    get_node("/root/Main/Players").add_child(p, true)
    p.set_multiplayer_authority(id)
    p.position = Vector2(id, id)

